//! Compare scripted backend stream gate to all twelve retained source rows.
use spore_core::cell_restore_stream_gate_v1::{project,Action,Resolver};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let b=std::fs::read(std::env::args().nth(1).expect("native stdout")).unwrap();assert_eq!(b.len(),384);for i in 0..12{let k=i%6;let cw=if i>=6{0x37f}else{0x27f};let enabled=k!=0;let first=if enabled{Some(if k<=2{0}else{1})}else{None};let second=if k>=3{Some(0xabcdef00)}else{None};let resolver=if k>=3{Some(Resolver{succeeded:k!=3,slot_after:if k==3{0xa5a5a5a5}else{0x55}})}else{None};let end=if k==1||k==4{Some(false)}else if k==2||k==5{Some(true)}else{None};let x=project(enabled,0xa5a5a5a5,first,second,resolver,end,cw,0x1f80,true).unwrap();let read=x.actions.iter().filter(|a|matches!(a,Action::ReadFirst|Action::ReadSecond)).count() as u32;let resolve=x.actions.iter().filter(|a|matches!(a,Action::Resolve{..})).count() as u32;let end=x.actions.iter().filter(|a|matches!(a,Action::End)).count() as u32;let get=u32::from(enabled)*0x10001;let row=&b[i*32..(i+1)*32];assert_eq!((w(row,0),w(row,4),w(row,8),w(row,12),w(row,16),w(row,28)),(u32::from(x.returned),x.slot,read,resolve,end,get));let fp=w(row,20);assert_eq!(fp&0xffff,cw as u32);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(row,24)&!0x3f,0x1f80);}println!("matched twelve retained backend stream gate rows; synthetic key and callbacks admitted");}
